// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1}(1);

        uint256 result = c.calculateTrade(1, 5000, 1);

        uint256 result2 = c.calculateTrade(1, 0, 1);
        assertTrue(result2 == 1, "calculateTrade should return 1 in reference");
    }
}
